        String[] tools={"pen","fountain","brush","pencil","marker","eraser","eraser","laser","compass"};for(int i=0;i<tools.length;i++){int x=80+i*177;if(i<8)ToolArt.draw(output,tools[i],x,75,2.3f,0xffb5b3ff,i==6?"stroke":"area");else ToolTextures.flat(output,"compass",x,170,140,Studio.ACCENT);label.setTextSize(16);output.drawText(i==5?"area":i==6?"stroke":tools[i],x-25,298,label);}
