        main(()->{NotesView v=detached[0];Ink.Doc layered=new Ink.Doc();layered.page().infinite=false;layered.page().pattern="blank";layered.page().width=920;layered.page().height=400;Ink.Layer foreground=new Ink.Layer();foreground.id="foreground";layered.page().layers.add(foreground);Ink.Stroke marker=line("marker",Color.BLUE,80,110,250);marker.layer=foreground.id;layered.page().strokes.add(marker);v.open(layered);v.tx=v.ty=0;v.fit=v.zoom=1;v.draft=line("pen",Color.RED,60,110,250);v.prepareDraftLayers();Bitmap frame=Bitmap.createBitmap(920,220,Bitmap.Config.ARGB_8888);v.draw(new Canvas(frame));int pixel=frame.getPixel(400,110);check(Color.blue(pixel)>=65&&Color.blue(pixel)<=74&&Color.red(pixel)>170,"live lower-layer draft stays beneath translucent foreground without double opacity");v.draft=null;v.draftUpper.clear();Ink.Stroke moved=line("pen",Color.RED,60,110,250);layered.page().strokes.add(0,moved);v.indexAll();v.rebuild();v.selection.add(moved);v.moving=true;v.moveDx=20;v.prepareMoveLayers();v.draw(new Canvas(frame));check(Color.blue(frame.getPixel(400,110))>=65&&Color.blue(frame.getPixel(400,110))<=74,"moving lower-layer lasso selection retains foreground opacity");v.moving=false;v.moveStack.clear();v.selection.clear();frame.recycle();});
